using FluentAssertions;
using TripCraft.Application.Workflows;
using TripCraft.Application.Workflows.Dtos;
using TripCraft.Application.Workflows.Ports;

namespace TripCraft.Tests.Workflows;

public class QuotationNameFallbackTests
{
    [Theory]
    [InlineData("guide")]
    [InlineData("vehicle")]
    [InlineData("room")]
    [InlineData("entry")]
    public void Missing_catalog_records_preserve_the_original_description(string type)
    {
        var facts = new ProposalFacts(new Dictionary<Guid, decimal>(), null, null,
            new Dictionary<Guid, RoomOption>(), false, false, null);
        var line = new ProposalQuotationLine(type, "Original description", 2, 125, 250);

        QuotationLineNames.Describe(line, facts).Should().Be("Original description");
        line.Should().Be(new ProposalQuotationLine(type, "Original description", 2, 125, 250));
    }

    [Fact]
    public void Room_identifiers_match_regardless_of_hex_letter_case()
    {
        var id = Guid.Parse("abcdefab-cdef-abcd-efab-cdefabcdefab");
        var facts = new ProposalFacts(new Dictionary<Guid, decimal>(), null, null,
            new Dictionary<Guid, RoomOption> { [id] = new(Guid.NewGuid(), "Hill Hotel", id, "Double", 2, 100) },
            false, false, null);
        var line = new ProposalQuotationLine("room", $"Room {id.ToString().ToUpperInvariant()}", 2, 100, 200);

        QuotationLineNames.Describe(line, facts).Should().Be("Hill Hotel — Double");
    }
}
